// One clean lead row per place. Re-runs update the same row (matched on placeId) instead of duplicating.
const out = [];
for (const it of $input.all()) {
  const p = it.json;
  if (!p.placeId) continue;
  out.push({ json: {
    placeId: p.placeId,
    name: p.title || '',
    category: p.categoryName || '',
    address: p.address || '',
    city: p.city || '',
    state: p.state || '',
    phone: p.phone || '',
    website: p.website || '',
    rating: p.totalScore ?? '',
    reviews: p.reviewsCount ?? '',
    claimedByOwner: p.claimedByOwner ?? '',
    permanentlyClosed: p.permanentlyClosed ?? '',
    googleMapsUrl: p.url || '',
    searchedFor: p.searchString || '',
    scrapedAt: p.scrapedAt || new Date().toISOString(),
  } });
}
return out;
